INSERT INTO moves VALUES (832, 'mystical-power', 90, 70, 'psychic', 10, 0, 0, 'special', 'generation-viii', 'The user strengthens itself with a mysterious power. If it excels in offense, its offensive stats are raised. If it excels in defense, its defensive stats are raised.', 'The user strengthens itself with a mysterious power. If it excels in offense, its offensive stats are raised. If it excels in defense, its defensive stats are raised.', '');
