INSERT INTO moves VALUES (835, 'chloroblast', 95, 150, 'grass', 5, 0, 0, 'special', 'generation-viii', 'The user launches its amassed chlorophyll to inflict damage on the target. This also damages the user and lowers the user''s action speed.', 'The user launches its amassed chlorophyll to inflict damage on the target. This also damages the user and lowers the user''s action speed.', '');
