INSERT INTO moves VALUES (851, 'tera-blast', 100, 80, 'normal', 10, 0, 0, 'special', 'generation-ix', 'If the user has Terastallized, it unleashes energy of its Tera Type. This move inflicts damage using the Attack or Sp. Atk stat—whichever is higher for the user.', 'If the user has Terastallized, it unleashes energy of its Tera Type. This move inflicts damage using the Attack or Sp. Atk stat—whichever is higher for the user.', '');
