INSERT INTO moves VALUES (905, 'electro-shot', 100, 130, 'electric', 10, 0, 0, 'special', 'generation-ix', 'The user gathers electricity on the first turn, boosting its Sp. Atk stat, then fires a high-voltage shot on the next turn. The shot will be fired immediately in rain.', 'The user gathers electricity on the first turn, boosting its Sp. Atk stat, then fires a high-voltage shot on the next turn. The shot will be fired immediately in rain.', '');
INSERT INTO moves VALUES (906, 'tera-starstorm', 100, 120, 'normal', 5, 0, 0, 'special', 'generation-ix', 'With the power of its crystals, the user bombards and eliminates the target. When used by Terapagos in its Stellar Form, this move damages all opposing Pokémon.', 'With the power of its crystals, the user bombards and eliminates the target. When used by Terapagos in its Stellar Form, this move damages all opposing Pokémon.', '');
INSERT INTO moves VALUES (907, 'fickle-beam', 100, 80, 'dragon', 5, 0, 0, 'special', 'generation-ix', 'The user shoots a beam of light to inflict damage. Sometimes all the user''s heads shoot beams in unison, doubling the move''s power.', 'The user shoots a beam of light to inflict damage. Sometimes all the user''s heads shoot beams in unison, doubling the move''s power.', '');
INSERT INTO moves VALUES (908, 'burning-bulwark', 0, 0, 'fire', 10, 0, 4, 'status', 'generation-ix', 'The user''s intensely hot fur protects it from attacks and also burns any attacker that makes direct contact with it.', 'The user''s intensely hot fur protects it from attacks and also burns any attacker that makes direct contact with it.', '');
INSERT INTO moves VALUES (909, 'thunderclap', 100, 70, 'electric', 5, 0, 1, 'special', 'generation-ix', 'This move enables the user to attack first with a jolt of electricity. This move fails if the target is not readying an attack.', 'This move enables the user to attack first with a jolt of electricity. This move fails if the target is not readying an attack.', '');
INSERT INTO moves VALUES (910, 'mighty-cleave', 100, 95, 'rock', 5, 0, 0, 'physical', 'generation-ix', 'The user wields the light that has accumulated atop its head to cleave the target. This move hits even if the target protects itself.', 'The user wields the light that has accumulated atop its head to cleave the target. This move hits even if the target protects itself.', '');
INSERT INTO moves VALUES (911, 'tachyon-cutter', 0, 50, 'steel', 10, 0, 0, 'special', 'generation-ix', 'The user attacks by launching particle blades at the target twice in a row. This attack never misses.', 'The user attacks by launching particle blades at the target twice in a row. This attack never misses.', '');
INSERT INTO moves VALUES (912, 'hard-press', 100, 0, 'steel', 10, 0, 0, 'physical', 'generation-ix', 'The target is crushed with an arm, a claw, or the like to inflict damage. The more HP the target has left, the greater the move''s power.', 'The target is crushed with an arm, a claw, or the like to inflict damage. The more HP the target has left, the greater the move''s power.', '');
INSERT INTO moves VALUES (913, 'dragon-cheer', 0, 0, 'dragon', 15, 0, 0, 'status', 'generation-ix', 'The user raises its allies’ morale with a draconic cry so that their future attacks have a heightened chance of landing critical hits. This rouses Dragon types more.', 'The user raises its allies’ morale with a draconic cry so that their future attacks have a heightened chance of landing critical hits. This rouses Dragon types more.', '');
INSERT INTO moves VALUES (914, 'alluring-voice', 100, 80, 'fairy', 10, 0, 0, 'special', 'generation-ix', 'The user attacks the target using its angelic voice. This also confuses the target if its stats have been boosted during the turn.', 'The user attacks the target using its angelic voice. This also confuses the target if its stats have been boosted during the turn.', '');
INSERT INTO moves VALUES (915, 'temper-flare', 100, 75, 'fire', 10, 0, 0, 'physical', 'generation-ix', 'Spurred by desperation, the user attacks the target. This move''s power is doubled if the user''s previous move failed.', 'Spurred by desperation, the user attacks the target. This move''s power is doubled if the user''s previous move failed.', '');
INSERT INTO moves VALUES (916, 'supercell-slam', 95, 100, 'electric', 15, 0, 0, 'physical', 'generation-ix', 'The user electrifies its body and drops onto the target to inflict damage. If this move misses, the user takes damage instead.', 'The user electrifies its body and drops onto the target to inflict damage. If this move misses, the user takes damage instead.', '');
INSERT INTO moves VALUES (917, 'psychic-noise', 100, 75, 'psychic', 10, 0, 0, 'special', 'generation-ix', 'The user attacks the target with unpleasant sound waves. For two turns, the target is prevented from recovering HP through moves, Abilities, or held items.', 'The user attacks the target with unpleasant sound waves. For two turns, the target is prevented from recovering HP through moves, Abilities, or held items.', '');
INSERT INTO moves VALUES (918, 'upper-hand', 100, 65, 'fighting', 15, 0, 3, 'physical', 'generation-ix', 'The user reacts to the target''s movement and strikes with the heel of its palm, making the target flinch. This move fails if the target is not readying a priority move.', 'The user reacts to the target''s movement and strikes with the heel of its palm, making the target flinch. This move fails if the target is not readying a priority move.', '');
INSERT INTO moves VALUES (919, 'malignant-chain', 100, 100, 'poison', 5, 0, 0, 'special', 'generation-ix', 'The user pours toxins into the target by wrapping them in a toxic, corrosive chain. This may also leave the target badly poisoned.', 'The user pours toxins into the target by wrapping them in a toxic, corrosive chain. This may also leave the target badly poisoned.', '');
